    for(const t of D.texts||[]){const a=t.ang||0,rot=((Math.round(a/(Math.PI/2))%4)+4)%4,L=String(t.t).length*4-1,w=rot%2?5:L,h=rot%2?L:5;ptext(x,String(t.t),Math.round(t.x*K-w/2),Math.round(t.y*K-h/2),t.col||'#ecece4',rot)}
    for(const o of W.pslots)if(o.num!=null){ptext(x,String(o.num),Math.round(o.cx)-2,Math.round(o.cy)-2,o.target?'#ffd23f':'#ecece4')}
