// ---- EXAMEN POR FASES de un plantel creado (D.exam): fase 1, fila, zigzag, rotonda, reversa, ALTO de 5 s, parqueo y salida
const DLG_INGRESO=[['INSTRUCTOR','¡Buenos días! Bienvenido al plantel. Deténgase aquí un momento, por favor.'],['INSTRUCTOR','Me permite su cédula, el dictamen médico y los papeles del carro.'],['INSTRUCTOR','(revisa los documentos) Todo en orden. Gracias.'],['INSTRUCTOR','Con calma, respire. ¡Mucha suerte, todo va a salir muy bien!']];
const DLG_FILA0=[['EVALUADOR','Ahora le voy a revisar el vehículo. Haga lo que le voy pidiendo, yo reviso por fuera.']];
const DLG_FILA1=[['EVALUADOR','Muy bien, el vehículo está en orden.'],['EVALUADOR','Ojo: en el examen oficial le van a revisar MÁS cosas: llantas, cinturón, luces de freno y de retroceso, limpiaparabrisas, asiento y espejos bien acomodados.'],['EVALUADOR','Prepárese con un instructor de manejo o vea videos de la prueba práctica de Ciudad Vial antes de ir.'],['EVALUADOR','Espere su turno en la fila. Cuando lo llamen, empieza la fase dos.']];
// SEMÁFOROS de los planteles creados: 3 luces (verde, amarillo, rojo) o 2 luces (verde y rojo). Ciclo en segundos, con desfase.
function semState(L,t){const g=L.verde,y=L.kind==='sem3'?L.amarillo:0,rd=L.rojo,T=g+y+rd,k=(((t+L.desfase)%T)+T)%T;return k<g?'V':k<g+y?'A':'R'}
function semRules(W,P,dt){for(const L of W.cLights){const dx=P.x-L.x,dy=P.y-L.y,al=dx*L.ux+dy*L.uy,lat=Math.abs(dy*L.ux-dx*L.uy),hd=Math.cos(P.h)*L.ux+Math.sin(P.h)*L.uy;
  if(lat<L.w+2&&hd>.3&&P.gear===1){if(L.prev!=null&&L.prev<=0&&al>0){const st=semState(L,S.t);if(st==='R')fault('semR'+L.id,'Pasarse el semáforo en ROJO','I',10);else if(st==='A'&&Math.abs(P.v)*KMH>15)toast('AMARILLO','Con amarillo se detiene si puede hacerlo con seguridad','info')}L.prev=al}else L.prev=null}}
const PHN={ingreso:'Ingreso',fase1:'Revisión del vehículo',fila:'Fila y revisión del vehículo',ir:'Recorrido (ALTO, CEDA y carril)',zigzag:'Zigzag',rotonda:'Rotonda',reversa:'Reversa',retroceso:'Retroceso en línea recta',alto5:'ALTO de 5 segundos',parar:'Parada con el evaluador',parqueo:'Estacionamiento',salida:'Salida'};
// ejercicio en el que va el examen (para el reporte final)
function curPh(){const k=S&&S.tasks&&S.tasks[S.task];if(!k)return null;if(k.ph)return k.ph;const m=(k.txt||'').match(/^([A-ZÁÉÍÓÚÑ0-9 ]{3,}?)\s*[:·]/);return m?m[1].charAt(0)+m[1].slice(1).toLowerCase():null}
function customExam(W,D){const K=4,E=D.exam;if(!E||!E.length)return null;const T=[],G=(x,y)=>({x:x*K,y:y*K}),near=(p,r)=>Math.hypot(S.P.x-p.x,S.P.y-p.y)<r*K;
  let ph0=0,lastSt=null;const tagPh=()=>{for(let i=ph0;i<T.length;i++)T[i].ph=T[i].ph||PHN[lastSt.tipo]||null;ph0=T.length};
  for(const st of E){if(lastSt)tagPh();lastSt=st;const p=st.x!=null?G(st.x,st.y):null;
    if(st.tipo==='fase1'){T.push({txt:(st.txt||'FASE 1: póngase el cinturón [C], avance despacio y deténgase junto al EVALUADOR.'),tgt:p,check(){if(this.dl||still('f1',near(p,6),.8))return dlgRun(this,CV2_F1);return false},ok:'¡Documentos en orden!'});
      for(const q of[['FASE 1 · Encienda las LUCES [L].',()=>!!S.P.lights,'Luces: bien'],['FASE 1 · Ponga la direccional IZQUIERDA [Q].',()=>!!S.P.blinkL,'Direccional izquierda: bien'],['FASE 1 · Ahora la direccional DERECHA [E].',()=>!!S.P.blinkR&&!S.P.blinkL,'Direccional derecha: bien'],
        ['FASE 1 · Ponga las luces de emergencia (intermitentes) [H].',()=>!!S.P.haz,'Intermitentes: bien'],['FASE 1 · Apague las intermitentes [H] y pise el FRENO [S] dos segundos.',()=>!S.P.haz&&still('frn',!!S.P.brake||(keys.s||keys.arrowdown),2),'Freno: bien']])T.push({txt:q[0],tgt:p,check:q[1],ok:q[2]});
      T.push({txt:'FASE 1 terminada. Escuche al evaluador.',tgt:p,check(){return dlgRun(this,CV2_F2)}})}
    else if(st.tipo==='ingreso')T.push({txt:st.txt||'INGRESO: avance hasta el ALTO y deténgase. El instructor le va a revisar los documentos.',tgt:p,check(){if(this.dl||still('ing',near(p,6),.8))return dlgRun(this,DLG_INGRESO);return false},ok:'¡Documentos en orden!'});
    else if(st.tipo==='parar'){const lines=(st.dlg||[]).map(t=>['EVALUADOR',t]);T.push({txt:st.txt||'Deténgase: el evaluador le va a explicar el ejercicio.',tgt:p,check(){if(this.dl||still('par'+T.length,near(p,st.r||6),.8))return dlgRun(this,lines.length?lines:[['EVALUADOR','Prepárese. Cuando esté listo, ya puede empezar.']]);return false},ok:'¡Ya puede empezar!'})}
    else if(st.tipo==='ir')T.push({txt:st.txt||'Siga hasta el punto marcado.',tgt:p,check(){return near(p,st.r||6)&&(!st.parar||Math.abs(S.P.v)<.5)}});
    else if(st.tipo==='fila'){T.push({txt:st.txt||'FILA: deténgase en la línea de ESPERE. El evaluador le va a revisar el vehículo.',tgt:p,check(){if(this.dl||still('fila',near(p,5),1.2))return dlgRun(this,DLG_FILA0);return false}});
      for(const q of[['REVISIÓN · Encienda las LUCES [L].',()=>!!S.P.lights,'Luces: bien'],['REVISIÓN · Direccional IZQUIERDA [Q].',()=>!!S.P.blinkL,'Direccional izquierda: bien'],['REVISIÓN · Direccional DERECHA [E].',()=>!!S.P.blinkR&&!S.P.blinkL,'Direccional derecha: bien'],
        ['REVISIÓN · Luces de emergencia (intermitentes) [H].',()=>!!S.P.haz,'Intermitentes: bien'],['REVISIÓN · Apague las intermitentes [H] y suene el PITO [B].',()=>!S.P.haz&&(S.P.hornT||0)>0,'Pito: bien'],
        ['REVISIÓN · Revise el espejo IZQUIERDO (mantenga [Z]).',()=>!!keys.z,'Espejo izquierdo: bien'],['REVISIÓN · Revise el espejo DERECHO (mantenga [X]).',()=>!!keys.x,'Espejo derecho: bien']])T.push({txt:q[0],tgt:p,check:q[1],ok:q[2]});
      T.push({txt:'Escuche al evaluador y espere su turno.',tgt:p,check(){return dlgRun(this,DLG_FILA1)},ok:'¡Su turno! Empieza la fase dos'})}
    else if(st.tipo==='zigzag')T.push({txt:st.txt||'ZIGZAG: pase entre los conos sin tocarlos (-12 por cono).',tgt:p,check(){return near(p,st.r||6)}});
    else if(st.tipo==='rotonda'){const g=(D.rings||[])[st.ring||0];if(!g)continue;const R={x:g.x*K,y:g.y*K,r:g.r*K};
      T.push({txt:st.txt||'ROTONDA: CEDA el paso al entrar, direccional IZQUIERDA [Q] adentro, VUELTA COMPLETA y salga con direccional DERECHA [E].',tgt:p||{x:R.x,y:R.y-R.r},start(){S.lap=0;S.la=null;S.inR=false;S.rsl=0},
        check(){const P=S.P,d=Math.hypot(P.x-R.x,P.y-R.y),w=(g.lanes||1)*(g.laneW||4.5)*K/2;if(d<R.r+w+2){const a=Math.atan2(P.y-R.y,P.x-R.x);if(S.la!=null)S.lap+=nA(a-S.la);S.la=a;S.inR=true;
          if(!(P.blinkL||P.blinkR)&&S.lap<-.8){S.rsl+=S.dt;if(S.rsl>1.5&&!this.f1){this.f1=1;fault('rsigL','No mantuvo la direccional IZQUIERDA dentro de la rotonda','III',3)}}return false}
          if(S.inR&&d>R.r+w+8){S.inR=false;S.la=null;if(S.lap>1)fault('rwrong','Circuló la rotonda en sentido contrario','I',5);else if(S.lap>-5.2)fault('lap','No dio la vuelta completa a la rotonda','II',6);
            if(!(P.blinkR||S.t-(P.lastR||-9)<2.5))fault('rsigR','No puso direccional DERECHA al salir de la rotonda','III',5);return true}return false}})}
    else if(st.tipo==='reversa'){const c=st.pts.map(([x,y])=>[x*K,y*K]),seg=[];let L=0;for(let i=0;i<c.length-1;i++){const a=c[i],b=c[i+1],l=Math.hypot(b[0]-a[0],b[1]-a[1]);seg.push({a,b,l,s0:L});L+=l}
      const proj=(x,y)=>{let best=null;for(const q of seg){const ux=(q.b[0]-q.a[0])/q.l,uy=(q.b[1]-q.a[1])/q.l,t=clamp((x-q.a[0])*ux+(y-q.a[1])*uy,0,q.l),px=q.a[0]+ux*t,py=q.a[1]+uy*t,d=Math.hypot(x-px,y-py),lat=(x-q.a[0])*(-uy)+(y-q.a[1])*ux;if(!best||d<best.d)best={d,s:q.s0+t,lat}}return best};
      const at=s=>{for(const q of seg)if(s<=q.s0+q.l){const t=s-q.s0;return{x:q.a[0]+(q.b[0]-q.a[0])*t/q.l,y:q.a[1]+(q.b[1]-q.a[1])*t/q.l}}return{x:c[c.length-1][0],y:c[c.length-1][1]}};
      const off=(st.carril||1.9)*K,lane=Math.random()<.5?-1:1,name=lane<0?'IZQUIERDO':'DERECHO',sEnd=L-(st.fin||2.5)*K,sBack=(st.atras||5)*K;
      T.push({txt:'Deténgase antes de los carriles de REVERSA: el evaluador le indica el carril.',tgt:at(1*K),check(){if(this.dl||still('rvq',Math.hypot(S.P.x-at(0).x,S.P.y-at(0).y)<10*K,1))return dlgRun(this,[['EVALUADOR','Deténgase aquí. Esta es la parte de CONDUCCIÓN EN REVERSA.'],['EVALUADOR','Le toca el carril '+name+'. Avance recto hasta el ALTO de los conos verdes y deténgase.'],['EVALUADOR','Luego retroceda en línea recta hasta pasar los conos verdes de atrás. Si toca un cono, pierde la prueba.'],['EVALUADOR','Prepárese. Cuando esté listo, ya puede empezar.']]);return false}});
      T.push({txt:'REVERSA: por el carril '+name+', avance hasta el ALTO y deténgase. Después retroceda recto hasta pasar los conos VERDES de atrás.',tgt:at(sEnd),ok:'¡Reversa completada!',
        check(){const P=S.P,q=proj(P.x,P.y),inL=q.d<off*2.2;if(!this.wl&&inL&&Math.sign(q.lat)!==lane&&Math.abs(q.lat)>off*.5&&q.s>sBack&&q.s<sEnd){this.wl=1;fault('rvlane','Usó el carril equivocado en la reversa','II',6)}
          if(!this.stg){if(inL&&q.s>sEnd-4*K&&Math.abs(P.v)<.4){this.stg=1;this.tgt=at(sBack);toast('AHORA EN REVERSA','Toque S dos veces y retroceda recto. Mire los espejos.','info');say('Ahora retroceda en línea recta.')}return false}
          if(inL&&P.gear===-1){if(P.v<-1)this.mv=true;if(this.mv&&Math.abs(P.v)<.3&&q.s>sBack+P.L){this.st=(this.st||0)+S.dt;if(this.st>1.2&&!this.fl){this.fl=1;fault('rstop','Detenerse durante el retroceso','IV',2)}}else this.st=0}
          if(q.s<sBack&&Math.abs(P.v)<.4){if(!this.mv)fault('rnoret','No realizó el retroceso en reversa','III',22);return true}return false}});
      T.push({txt:'Avance otra vez hasta el ALTO y deténgase COMPLETAMENTE (cuente 5 segundos).',tgt:at(sEnd),check(){const P=S.P,q=proj(P.x,P.y);if(q.d<off*2.2&&q.s>sEnd-4*K&&Math.abs(P.v)<.3)this.w=(this.w||0)+S.dt;else if(this.w&&this.w<3&&q.s>sEnd){fault('alto5','Arrancó del ALTO sin detenerse lo suficiente','II',6);this.w=99}return this.w>=4.5},ok:'¡Buen ALTO!'})}
    else if(st.tipo==='retroceso'){const c=st.pts.map(([x,y])=>[x*K,y*K]),seg=[];let L=0;for(let i=0;i<c.length-1;i++){const a=c[i],b=c[i+1],l=Math.hypot(b[0]-a[0],b[1]-a[1]);seg.push({a,b,l,s0:L});L+=l}
      const proj=(x,y)=>{let best=null;for(const q of seg){const ux=(q.b[0]-q.a[0])/q.l,uy=(q.b[1]-q.a[1])/q.l,t=clamp((x-q.a[0])*ux+(y-q.a[1])*uy,0,q.l),d=Math.hypot(x-q.a[0]-ux*t,y-q.a[1]-uy*t);if(!best||d<best.d)best={d,s:q.s0+t}}return best};
      const A={x:c[0][0],y:c[0][1]},B={x:c[c.length-1][0],y:c[c.length-1][1]},ancho=(st.ancho||2.5)*K;
      // retroceso: llegar al inicio de la línea, detenerse y retroceder recto hasta el final, sin salirse ni detenerse a medio camino
      T.push({txt:st.txt||'RETROCESO: deténgase al inicio de la línea blanca y retroceda recto por ella, sin detenerse, hasta volver al punto marcado.',tgt:A,ok:'¡Retroceso completado!',
        start(){this.stg=0;this.mv=false;this.st=0},
        check(){const P=S.P,q=proj(P.x,P.y);
          if(!this.stg){if(Math.hypot(P.x-A.x,P.y-A.y)<5*K&&Math.abs(P.v)<.4){this.stg=1;this.tgt=B;toast('AHORA EN REVERSA','Toque S dos veces y retroceda recto por la línea blanca. Mire los espejos.','info');say('Ahora retroceda en línea recta por la línea blanca.')}return false}
          if(P.gear===-1&&P.v<-1)this.mv=true;
          if(this.mv&&q.d>ancho&&!this.fo){this.fo=1;fault('rtline','Se salió de la línea durante el retroceso','II',6)}
          if(this.mv&&Math.abs(P.v)<.3&&q.s<L-4*K){this.st+=S.dt;if(this.st>1.5&&!this.fl){this.fl=1;fault('rstop','Detenerse durante el retroceso','IV',2)}}else this.st=0;
          if(this.mv&&q.s>=L-3*K&&Math.abs(P.v)<.4)return true;
          if(!this.mv&&P.gear===1&&P.v>2&&q.s>4*K&&!this.nr){this.nr=1;fault('rnoret','No realizó el retroceso en reversa','III',22)}
          return false}})}
    else if(st.tipo==='alto5')T.push({txt:st.txt||'Haga ALTO completo (5 segundos).',tgt:p,check(){if(near(p,4)&&Math.abs(S.P.v)<.3)this.w=(this.w||0)+S.dt;return this.w>=4.5},ok:'¡Buen ALTO!'});
    else if(st.tipo==='parqueo'){const o=W.pslot;if(!o)continue;T.push({txt:'ESTACIONAMIENTO EN REVERSA: estaciónese de retroceso en el espacio '+(o.num||'')+' (el amarillo). Tiene 5 intentos. Si toca un cono pierde la prueba.',tgt:{x:o.cx,y:o.cy},ok:'¡Estacionamiento correcto!',
      start(){this.tries=0;this.lg=1;S.dlg={lines:[['EVALUADOR','Vaya y estaciónese de retroceso en el espacio '+(o.num||'')+'. Tiene cinco intentos.']],i:0,t:0,auto:true}},
      check(){const P=S.P,dx=P.x-o.cx,dy=P.y-o.cy,c=Math.cos(o.ang),s=Math.sin(o.ang),al=dx*c+dy*s,lt=-dx*s+dy*c;if(Math.hypot(dx,dy)<10*K&&P.gear===-1&&this.lg===1){this.tries++;if(this.tries>5)fatal('Más de cinco intentos para estacionar: prueba perdida');else if(this.tries>1)toast('INTENTO '+this.tries+' DE 5','','info')}this.lg=P.gear;
        return still('cpx',Math.abs(al)<o.hl*.45&&Math.abs(lt)<o.hw*.5&&Math.cos(P.h-o.ang)>.93,1.2)}})}
    else if(st.tipo==='salida')T.push({txt:st.txt||'¡Fase dos terminada! Siga hasta la SALIDA.',tgt:p,check(){const P=S.P;if(!this.ar&&near(p,st.r||7))this.ar=1;if(this.ar){P.v*=.85;if(Math.abs(P.v)<.3)P.v=0;P.thr=0;P.brake=true;if(Math.abs(P.v)<.5)return dlgRun(this,[['EVALUADOR','Deténgase aquí. ¡Felicidades!'],['EVALUADOR','PASÓ EL PLANTEL. Lo hizo muy bien.'],['EVALUADOR','(se sube al carro) Ahora vamos para la fase tres: el recorrido en calle. Con calma, siga mis indicaciones.']])}return false},ok:'¡PASÓ EL PLANTEL!'})}
  if(lastSt)tagPh();return T.length?T:null}
function customTasks(){const W=S.W,o=W.pslot;{const X=customExam(W,W.custom);if(X)return X}const T=[];
  if(o)T.push({txt:'MI PLANTEL: estaciónese de RETROCESO en el espacio amarillo'+(o.num?' ('+o.num+')':'')+'. Respete ALTO y CEDA y no toque conos.',tgt:{x:o.cx,y:o.cy},ok:'¡Estacionamiento correcto!',
    check(){const P=S.P,dx=P.x-o.cx,dy=P.y-o.cy,c=Math.cos(o.ang),s=Math.sin(o.ang),al=dx*c+dy*s,lt=-dx*s+dy*c;return still('cst',Math.abs(al)<o.hl*.45&&Math.abs(lt)<o.hw*.45&&Math.cos(P.h-o.ang)>.93,1.2)}});
  T.push({txt:(S.mode==='heredia'?'PLANTEL DE HEREDIA':'MI PLANTEL')+': practique libremente. Respete los ALTO y CEDA, use direccionales y no toque conos. [ESC] para salir.',tgt:{x:W.spawn.x,y:W.spawn.y},check(){return false}});
  return T}
